(function(){
  const D=window.KARDEX_DATA,S=window.KARDEX_STORE;
  const titles={dashboard:'Inicio',preregistro:'Pre-registro y requisitos',ficha:'Ficha personal',hojavida:'Hoja de vida',formularios:'Formularios de ingreso',familia:'Familia y parentesco',caja:'Caja de Salud',vacaciones:'Vacaciones',certificados:'Certificados de trabajo',accidentes:'Accidentes de trabajo',historial:'Historial del funcionario',mapa:'Mapa de datos'};
  const esc=v=>String(v??'').replace(/[&<>'"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[m]));
  const today=()=>new Date().toISOString().slice(0,10);
  const age=d=>{if(!d)return'';const b=new Date(d+'T00:00:00'),n=new Date();let a=n.getFullYear()-b.getFullYear();if(n<new Date(n.getFullYear(),b.getMonth(),b.getDate()))a--;return a;};
  const p=()=>S.get().profile;
  function fieldHTML(group,spec){const [key,label,type,opts]=spec;const val=(p()[group]||{})[key]??''; if(type==='select')return `<div class="field"><label>${esc(label)}</label><select data-bind="profile.${group}.${key}"><option value=""></option>${opts.map(o=>`<option ${String(val)===o?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;return `<div class="field"><label>${esc(label)}</label><input type="${type}" value="${esc(val)}" data-bind="profile.${group}.${key}"></div>`}
  function bindInputs(root=document){root.querySelectorAll('[data-bind]').forEach(el=>{el.addEventListener('change',()=>{S.set(el.dataset.bind,el.type==='checkbox'?el.checked:el.value);if(el.dataset.bind==='profile.persona.fecha_nacimiento')renderFicha();});});}
  function addHistory(tipo,detalle){S.push('historial',{fecha:today(),tipo,detalle});}
  function showModal(title,html){document.getElementById('modalTitle').textContent=title;document.getElementById('modalBody').innerHTML=html;document.getElementById('modal').classList.add('open');}
  function closeModal(){document.getElementById('modal').classList.remove('open')}
  function setView(name){document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.getElementById('view-'+name).classList.add('active');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));document.getElementById('topTitle').textContent=titles[name]||name;S.set('ui.activeView',name);const f=renderers[name];if(f)f();window.scrollTo({top:0,behavior:'smooth'});}
  function personName(){const x=p().persona||{};return [x.nombres,x.apellido_paterno,x.apellido_materno].filter(Boolean).join(' ')}
  function profileSummary(){const pr=p();return `${esc(personName())} · C.I. ${esc(pr.persona.ci||'—')} · Ítem ${esc(pr.institucional.numero_item||'—')}`}
  function saveNotice(btn){const old=btn.textContent;btn.textContent='Guardado ✓';setTimeout(()=>btn.textContent=old,1200)}

  function renderDashboard(){const st=S.get();const done=st.checklist.filter(x=>x.estado==='PRESENTADO').length;const hist=st.historial.length;const vac=st.vacaciones.length;const acc=st.accidentes.length;document.getElementById('view-dashboard').innerHTML=`
    <div class="page-head"><div><h3>Prototipo Kardex Digital</h3><p>Recorrido funcional para validar con Kardex cómo se registrará la información desde el pre-ingreso hasta los procesos posteriores, sin digitalizar archivos pesados.</p></div></div>
    <div class="grid four"><div class="kpi"><strong>${done}/25</strong><span>Requisitos presentados</span></div><div class="kpi"><strong>${hist}</strong><span>Eventos en historial</span></div><div class="kpi"><strong>${vac}</strong><span>Vacaciones registradas</span></div><div class="kpi"><strong>${acc}</strong><span>Accidentes registrados</span></div></div>
    <div class="card" style="margin-top:16px"><h4>Flujo propuesto</h4><div class="flow">
      ${[['1','Pre-registro','Identificación mínima'],['2','Checklist Kardex','25 requisitos'],['3','RR.HH.','Memorándum designación'],['4','Ficha / Hoja de Vida','Datos completos'],['5','Formularios','Posesión, inducción y declaraciones'],['6','Kardex activo','Procesos recurrentes'],['7','Historial','Trazabilidad']].map((x,i)=>`${i?'<div class="arrow">→</div>':''}<div class="step"><b>${x[0]}. ${x[1]}</b>${x[2]}</div>`).join('')}
    </div></div>
    <div class="grid two" style="margin-top:16px"><div class="card"><h4>Persona seleccionada</h4><p>${profileSummary()}</p><div class="chips"><span class="chip">Ficha reutilizable</span><span class="chip">Sin escaneos</span><span class="chip">Datos estructurados</span><span class="chip">Exportables</span></div></div><div class="card"><h4>Principio de diseño</h4><div class="callout">Nombre, C.I., fecha de nacimiento, ítem, CUA y cargo se registran una sola vez y luego se autocompletan en vacaciones, Caja de Salud, certificados y accidentes.</div></div></div>`}

  function renderPreregistro(){const st=S.get();const presented=st.checklist.filter(x=>x.estado==='PRESENTADO').length;const applicable=st.checklist.filter(x=>x.estado!=='NO CORRESPONDE').length;const pct=applicable?Math.round(presented/applicable*100):100;document.getElementById('view-preregistro').innerHTML=`
    <div class="page-head"><div><h3>Pre-registro y checklist de ingreso</h3><p>Kardex identifica al interesado y marca el estado de cada requisito. No se almacena el documento escaneado; solo el control de presentación/verificación.</p></div><div class="toolbar"><button class="btn primary" id="validateChecklist">Validar checklist</button><button class="btn" id="sendRRHH">Enviar conformidad a RR.HH.</button></div></div>
    <div class="card"><div class="form-grid">${['ci','nombres','apellido_paterno','apellido_materno'].map(k=>fieldHTML('persona',D.fields.persona.find(f=>f[0]===k))).join('')}${fieldHTML('institucional',D.fields.institucional[0])}<div class="field"><label>Fecha de notificación</label><input type="date" value="${esc(st.preregistro.fecha_notificacion)}" data-bind="preregistro.fecha_notificacion"></div></div></div>
    <div class="card" style="margin-top:16px"><div class="section-title"><h4>Boleta de requisitos Kardex 2026</h4><span><b>${presented}</b> presentados · ${pct}%</span></div><div class="progress"><div style="width:${pct}%"></div></div><div class="table-wrap" style="margin-top:12px"><table><thead><tr><th>N°</th><th>Requisito</th><th>Estado</th><th>Observación</th></tr></thead><tbody>${st.checklist.map((r,i)=>`<tr><td>${r.numero}</td><td>${esc(r.nombre)}</td><td><select class="req-status" data-i="${i}"><option ${r.estado==='PENDIENTE'?'selected':''}>PENDIENTE</option><option ${r.estado==='PRESENTADO'?'selected':''}>PRESENTADO</option><option ${r.estado==='NO CORRESPONDE'?'selected':''}>NO CORRESPONDE</option></select></td><td><input class="req-obs" data-i="${i}" value="${esc(r.observacion)}" placeholder="Opcional"></td></tr>`).join('')}</tbody></table></div><p class="tiny muted">La boleta indica entrega dentro de 5 días hábiles desde la notificación.</p></div>
    <div class="card" style="margin-top:16px"><h4>Confirmación desde RR.HH.</h4><div class="form-grid"><div class="field"><label>Nº Memorándum de Designación</label><input value="${esc(st.preregistro.memo_numero)}" data-bind="preregistro.memo_numero"></div><div class="field"><label>Fecha de Memorándum</label><input type="date" value="${esc(st.preregistro.memo_fecha)}" data-bind="preregistro.memo_fecha"></div><div class="field"><label>Estado</label><input class="readonly" readonly value="${st.preregistro.rrhh_confirmado?'DESIGNACIÓN RECIBIDA':'PENDIENTE RR.HH.'}"></div></div><div class="toolbar" style="margin-top:12px"><button class="btn success" id="confirmMemo">Confirmar memorándum recibido</button></div></div>`;
    bindInputs();document.querySelectorAll('.req-status').forEach(x=>x.onchange=()=>{const a=S.get().checklist;a[+x.dataset.i].estado=x.value;S.save();renderPreregistro()});document.querySelectorAll('.req-obs').forEach(x=>x.onchange=()=>{S.get().checklist[+x.dataset.i].observacion=x.value;S.save()});document.getElementById('validateChecklist').onclick=()=>alert(pct===100?'Checklist completo para los requisitos aplicables.':'Aún existen requisitos pendientes.');document.getElementById('sendRRHH').onclick=()=>{S.set('preregistro.estado','ENVIADO_RRHH');addHistory('INGRESO','Kardex remitió conformidad de requisitos a RR.HH.');alert('Simulación: conformidad enviada a RR.HH.')};document.getElementById('confirmMemo').onclick=()=>{if(!S.get().preregistro.memo_numero)return alert('Ingrese el número de memorándum.');S.set('preregistro.rrhh_confirmado',true);addHistory('DESIGNACIÓN',`Memorándum de Designación ${S.get().preregistro.memo_numero} recibido por Kardex`);renderPreregistro()}}

  function renderFicha(){const pr=p();document.getElementById('view-ficha').innerHTML=`<div class="page-head"><div><h3>Ficha personal y datos maestros</h3><p>Los datos se registran una sola vez. Edad y otros valores derivados se calculan para evitar duplicaciones.</p></div><button class="btn primary" id="saveFicha">Guardar ficha</button></div>
    <div class="card"><div class="tabs"><button class="tab active" data-tab="personales">Datos personales</button><button class="tab" data-tab="academicos">Datos académicos</button><button class="tab" data-tab="institucionales">Datos institucionales</button><button class="tab" data-tab="seguridad">Bancarios / seguridad social</button><button class="tab" data-tab="control">Control actual</button></div>
      <div class="tabpane active" data-pane="personales"><div class="form-grid">${D.fields.persona.map(f=>fieldHTML('persona',f)).join('')}<div class="field"><label>Edad (calculada)</label><input class="readonly" readonly value="${age(pr.persona.fecha_nacimiento)||''}"></div></div><div class="section-title"><h4>Contacto de emergencia</h4></div><div class="form-grid">${D.fields.emergencia.map(f=>fieldHTML('emergencia',f)).join('')}</div></div>
      <div class="tabpane" data-pane="academicos"><div class="callout">La Ficha Personal maneja cinco niveles: Bachiller, Técnico Medio o Superior, Egresado, Licenciatura y Títulos de Postgrado. El detalle completo se registra en Hoja de Vida para no duplicar información.</div>${academicQuickTable()}</div>
      <div class="tabpane" data-pane="institucionales"><div class="form-grid">${D.fields.institucional.map(f=>fieldHTML('institucional',f)).join('')}</div></div>
      <div class="tabpane" data-pane="seguridad"><div class="form-grid">${D.fields.bancario.map(f=>fieldHTML('bancario',f)).join('')}</div></div>
      <div class="tabpane" data-pane="control"><div class="callout warn">Estos campos existen actualmente en avance.xlsx y se mantienen para validación del responsable de Kardex.</div><div class="form-grid" style="margin-top:12px">${D.fields.control_actual.map(f=>fieldHTML('control_actual',f)).join('')}</div></div>
    </div>`;bindInputs();document.querySelectorAll('.tab').forEach(t=>t.onclick=()=>{document.querySelectorAll('.tab,.tabpane').forEach(x=>x.classList.remove('active'));t.classList.add('active');document.querySelector(`[data-pane="${t.dataset.tab}"]`).classList.add('active')});document.getElementById('saveFicha').onclick=e=>{addHistory('FICHA PERSONAL','Datos personales e institucionales actualizados');saveNotice(e.currentTarget)}}
  function academicQuickTable(){const f=S.get().hojaVida.formacion;return `<div class="table-wrap" style="margin-top:14px"><table><thead><tr><th>Grado / título</th><th>Carrera / área / especialidad</th><th>Universidad / institución</th></tr></thead><tbody>${f.length?f.map(x=>`<tr><td>${esc(x.titulo||x.grado||'')}</td><td>${esc(x.area||'')}</td><td>${esc(x.institucion||'')}</td></tr>`).join(''):'<tr><td colspan="3" class="muted">Sin registros. Agréguelos desde Hoja de Vida.</td></tr>'}</tbody></table></div>`}

  function renderHojaVida(){const hv=S.get().hojaVida;document.getElementById('view-hojavida').innerHTML=`<div class="page-head"><div><h3>Hoja de Vida Digital</h3><p>Los datos personales ya existentes se autocompletan. Aquí se registra únicamente la información repetible: estudios, cursos, experiencia y referencias.</p></div><button class="btn" id="previewCV">Vista previa</button></div>
    <div class="card"><h4>Datos autocompletados</h4><div class="chips"><span class="chip">${profileSummary()}</span><span class="chip">Nacimiento: ${esc(p().persona.fecha_nacimiento||'—')}</span><span class="chip">Celular: ${esc(p().persona.telefono||'—')}</span><span class="chip">Banco Unión: ${esc(p().bancario.numero_cuenta_banco_union||'—')}</span><span class="chip">CENVI: ${esc(p().bancario.fecha_certificacion_cenvi||'—')}</span></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Fecha de presentación</label><input type="date" value="${esc(hv.fecha_presentacion)}" id="hvFecha"></div></div></div>
    ${repeatSection('Bachillerato','bachillerato',[['bachillerato','Bachillerato'],['colegio','Colegio'],['anio_egreso','Año / fecha de egreso']])}
    ${repeatSection('Doctorados / Maestrías / Licenciaturas / Estudios Técnicos','formacion',[['titulo','Título / grado'],['area','Carrera / área / especialidad'],['institucion','Institución'],['fecha_extension','Fecha de extensión del título']])}
    ${repeatSection('Cursos / Seminarios / Talleres','cursos',[['nombre','Curso / Seminario / Taller'],['fecha_inicio','Fecha inicio'],['fecha_fin','Fecha finalización'],['duracion','Duración (horas)']])}
    ${repeatSection('Experiencia de trabajo','experiencia',[['entidad','Entidad / Empresa'],['cargo','Cargo desempeñado'],['fecha_inicio','Fecha inicio (Mes/Año)'],['fecha_fin','Fecha culminación (Mes/Año)']])}
    ${repeatSection('Referencias personales','referencias',[['entidad','Entidad / Empresa'],['cargo_referencia','Cargo de la persona de referencia'],['nombre','Nombre de la persona'],['telefono','Teléfonos actualizados']])}`;
    document.getElementById('hvFecha').onchange=e=>S.set('hojaVida.fecha_presentacion',e.target.value);document.querySelectorAll('[data-addrow]').forEach(b=>b.onclick=()=>addRow(b.dataset.addrow));document.querySelectorAll('[data-delrow]').forEach(b=>b.onclick=()=>delRow(b.dataset.group,+b.dataset.delrow));document.getElementById('previewCV').onclick=()=>showModal('Hoja de Vida',cvPreview())}
  function repeatSection(title,group,cols){const arr=S.get().hojaVida[group];return `<div class="card" style="margin-top:16px"><div class="section-title"><h4>${title}</h4><button class="btn small" data-addrow="${group}">+ Agregar</button></div><div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${c[1]}</th>`).join('')}<th></th></tr></thead><tbody>${arr.length?arr.map((r,i)=>`<tr>${cols.map(c=>`<td>${esc(r[c[0]]||'')}</td>`).join('')}<td><button class="btn small danger" data-group="${group}" data-delrow="${i}">Quitar</button></td></tr>`).join(''):`<tr><td colspan="${cols.length+1}" class="muted">Sin registros</td></tr>`}</tbody></table></div></div>`}
  function addRow(group){const defs={bachillerato:[['bachillerato','Bachillerato'],['colegio','Colegio'],['anio_egreso','Año / fecha de egreso']],formacion:[['titulo','Título / grado'],['area','Carrera / área / especialidad'],['institucion','Institución'],['fecha_extension','Fecha de extensión']],cursos:[['nombre','Curso / Seminario / Taller'],['fecha_inicio','Fecha inicio'],['fecha_fin','Fecha finalización'],['duracion','Duración horas']],experiencia:[['entidad','Entidad / Empresa'],['cargo','Cargo desempeñado'],['fecha_inicio','Fecha inicio'],['fecha_fin','Fecha culminación']],referencias:[['entidad','Entidad / Empresa'],['cargo_referencia','Cargo referencia'],['nombre','Nombre referencia'],['telefono','Teléfono']]};const fields=defs[group];showModal('Agregar registro',`<div class="form-grid">${fields.map(f=>`<div class="field"><label>${f[1]}</label><input id="add_${f[0]}"></div>`).join('')}</div><div class="toolbar" style="margin-top:16px"><button class="btn primary" id="confirmAdd">Guardar</button></div>`);document.getElementById('confirmAdd').onclick=()=>{const obj={};fields.forEach(f=>obj[f[0]]=document.getElementById('add_'+f[0]).value);S.push('hojaVida.'+group,obj);closeModal();renderHojaVida()}}
  function delRow(group,i){S.get().hojaVida[group].splice(i,1);S.save();renderHojaVida()}
  function cvPreview(){const st=S.get(),hv=st.hojaVida;return `<div class="preview"><h1>CURRICULUM VITAE</h1><p><b>${esc(personName())}</b><br>C.I. ${esc(p().persona.ci)} · ${esc(p().persona.nacionalidad)} · ${esc(p().persona.correo)}</p><h3>Estudios realizados</h3>${simpleList(hv.formacion,x=>`${x.titulo||''} — ${x.institucion||''}`)}<h3>Cursos / seminarios</h3>${simpleList(hv.cursos,x=>`${x.nombre||''} (${x.duracion||''} h)`)}<h3>Experiencia de trabajo</h3>${simpleList(hv.experiencia,x=>`${x.entidad||''} — ${x.cargo||''}`)}<h3>Referencias personales</h3>${simpleList(hv.referencias,x=>`${x.nombre||''} — ${x.telefono||''}`)}<p class="tiny">Fecha de presentación: ${esc(hv.fecha_presentacion||'')}</p></div>`}
  function simpleList(arr,fmt){return arr.length?'<ul>'+arr.map(x=>`<li>${esc(fmt(x))}</li>`).join('')+'</ul>':'<p class="muted">Sin registros.</p>'}

  function renderFormularios(){const f=S.get().formularios;const pr=p();document.getElementById('view-formularios').innerHTML=`<div class="page-head"><div><h3>Formularios internos de ingreso</h3><p>Los formularios se generan desde los datos registrados; no se suben como PDF o fotografía.</p></div></div>
    <div class="grid two">
      <div class="card"><h4>Acta de Posesión</h4><div class="form-grid"><div class="field"><label>Ciudad</label><input id="pos_ciudad" value="${esc(f.posesion.ciudad)}"></div><div class="field"><label>Fecha</label><input type="date" id="pos_fecha" value="${esc(f.posesion.fecha)}"></div><div class="field"><label>Hora</label><input type="time" id="pos_hora" value="${esc(f.posesion.hora)}"></div><div class="field"><label>Nº ítem</label><input id="pos_item" value="${esc(f.posesion.numero_item||pr.institucional.numero_item)}"></div><div class="field wide"><label>Cargo</label><input id="pos_cargo" value="${esc(f.posesion.cargo||pr.institucional.denominacion_puesto)}"></div></div><div class="toolbar" style="margin-top:12px"><button class="btn primary" data-formpreview="posesion">Generar acta</button></div></div>
      <div class="card"><h4>Acta de Inducción</h4><div class="form-grid"><div class="field"><label>Inmediato superior</label><input id="ind_superior" value="${esc(f.induccion.inmediato_superior)}"></div><div class="field"><label>Dependencia</label><input id="ind_dep" value="${esc(f.induccion.dependencia||pr.institucional.unidad_administrativa)}"></div><div class="field"><label>Nº ítem</label><input id="ind_item" value="${esc(f.induccion.numero_item||pr.institucional.numero_item)}"></div><div class="field"><label>Fecha</label><input type="date" id="ind_fecha" value="${esc(f.induccion.fecha)}"></div></div><div class="table-wrap" style="margin-top:10px"><table><tbody>${f.induccion.documentos.map((x,i)=>`<tr><td><input type="checkbox" class="inddoc" data-i="${i}" ${x.entregado?'checked':''}></td><td>${esc(x.nombre)}</td></tr>`).join('')}</tbody></table></div><div class="toolbar" style="margin-top:12px"><button class="btn primary" data-formpreview="induccion">Generar acta</button></div></div>
      <div class="card"><h4>Declaración Jurada – Doble Percepción</h4>${doubleFormHTML(f.doble)}<div class="toolbar" style="margin-top:12px"><button class="btn primary" data-formpreview="doble">Generar declaración</button></div></div>
      <div class="card"><h4>Declaración de Incompatibilidades, Conflicto de Interés y Prohibiciones</h4><p class="tiny muted">El formulario institucional contiene el marco legal y una declaración final del servidor público.</p><label><input type="checkbox" id="inc_acepta" ${f.incompatibilidad.acepta?'checked':''}> Declaro no estar comprendido en las incompatibilidades, conflictos de interés y prohibiciones señaladas en el formulario.</label><div class="field" style="margin-top:10px"><label>Fecha de declaración</label><input type="date" id="inc_fecha" value="${esc(f.incompatibilidad.fecha_declaracion)}"></div><div class="toolbar" style="margin-top:12px"><button class="btn primary" data-formpreview="incompatibilidad">Generar declaración</button></div></div>
    </div>`;
    document.querySelectorAll('.inddoc').forEach(x=>x.onchange=()=>{S.get().formularios.induccion.documentos[+x.dataset.i].entregado=x.checked;S.save()});document.querySelectorAll('[data-formpreview]').forEach(b=>b.onclick=()=>saveAndPreviewForm(b.dataset.formpreview))}
  function doubleFormHTML(x){return `<div class="form-grid"><div class="field"><label>Percibe recursos del Estado</label><select id="dob_percibe"><option value="false" ${!x.percibe_recursos?'selected':''}>NO</option><option value="true" ${x.percibe_recursos?'selected':''}>SI</option></select></div><div class="field"><label>Tipo de ingreso</label><select id="dob_tipo"><option></option>${['Remuneración','Pensión','Docencia','Otros'].map(o=>`<option ${x.tipo_ingreso===o?'selected':''}>${o}</option>`).join('')}</select></div><div class="field"><label>Otros (especifique)</label><input id="dob_otro" value="${esc(x.otro_tipo)}"></div><div class="field"><label>Entidad donde percibe</label><input id="dob_entidad" value="${esc(x.entidad)}"></div><div class="field"><label>Fecha desde que percibe</label><input type="date" id="dob_inicio" value="${esc(x.fecha_inicio)}"></div><div class="field"><label>Importe mensual</label><input type="number" id="dob_importe" value="${esc(x.importe)}"></div><div class="field"><label>Régimen de pensión</label><input id="dob_regimen" value="${esc(x.regimen_pension)}"></div><div class="field"><label>Entidad para aguinaldo</label><input id="dob_aguinaldo" value="${esc(x.entidad_aguinaldo)}"></div><div class="field"><label>¿Es jubilado?</label><select id="dob_jub"><option value="false" ${!x.es_jubilado?'selected':''}>NO</option><option value="true" ${x.es_jubilado?'selected':''}>SI</option></select></div><div class="field"><label>¿Realizó trámite para cesar renta?</label><select id="dob_cese"><option value="false" ${!x.tramite_cese?'selected':''}>NO</option><option value="true" ${x.tramite_cese?'selected':''}>SI</option></select></div><div class="field"><label>Fecha declaración</label><input type="date" id="dob_fecha" value="${esc(x.fecha_declaracion)}"></div></div>`}
  function saveAndPreviewForm(type){const f=S.get().formularios,pr=p();if(type==='posesion'){Object.assign(f.posesion,{ciudad:elv('pos_ciudad'),fecha:elv('pos_fecha'),hora:elv('pos_hora'),numero_item:elv('pos_item'),cargo:elv('pos_cargo')});S.save();showModal('Acta de Posesión',`<div class="preview"><h2>ACTA DE POSESIÓN</h2><p>En la ciudad de <b>${esc(f.posesion.ciudad)}</b> a hrs. <b>${esc(f.posesion.hora)}</b> del día <b>${esc(f.posesion.fecha)}</b> fue posesionado(a) el/la servidor(a) público(a) <b>${esc(personName())}</b>, con C.I. <b>${esc(pr.persona.ci)}</b>, con el ítem Nº <b>${esc(f.posesion.numero_item)}</b>, en el cargo de <b>${esc(f.posesion.cargo)}</b>.</p><div class="sign"><div>Firma Servidor Público Posesionado</div><div>Firma Jefe Inmediato Superior</div></div></div>`)}
    if(type==='induccion'){Object.assign(f.induccion,{inmediato_superior:elv('ind_superior'),dependencia:elv('ind_dep'),numero_item:elv('ind_item'),fecha:elv('ind_fecha')});S.save();showModal('Acta de Inducción',`<div class="preview"><h2>ACTA DE INDUCCIÓN</h2><p><b>Servidor:</b> ${esc(personName())}<br><b>Inmediato superior:</b> ${esc(f.induccion.inmediato_superior)}<br><b>Dependencia:</b> ${esc(f.induccion.dependencia)}<br><b>Ítem:</b> ${esc(f.induccion.numero_item)}</p><ul>${f.induccion.documentos.map(x=>`<li>${x.entregado?'☑':'☐'} ${esc(x.nombre)}</li>`).join('')}</ul><p>Fecha: ${esc(f.induccion.fecha)}</p></div>`)}
    if(type==='doble'){Object.assign(f.doble,{percibe_recursos:elv('dob_percibe')==='true',tipo_ingreso:elv('dob_tipo'),otro_tipo:elv('dob_otro'),entidad:elv('dob_entidad'),fecha_inicio:elv('dob_inicio'),importe:elv('dob_importe'),regimen_pension:elv('dob_regimen'),entidad_aguinaldo:elv('dob_aguinaldo'),es_jubilado:elv('dob_jub')==='true',tramite_cese:elv('dob_cese')==='true',fecha_declaracion:elv('dob_fecha')});S.save();showModal('Declaración Jurada – Doble Percepción',`<div class="preview"><h2>DECLARACIÓN JURADA – INCOMPATIBILIDAD DE DOBLE PERCEPCIÓN</h2><p>Yo <b>${esc(personName())}</b>, C.I. <b>${esc(pr.persona.ci)}</b>, declaro:</p><p>Percibo recursos económicos del Estado: <b>${f.doble.percibe_recursos?'SI':'NO'}</b></p>${f.doble.percibe_recursos?`<p>Tipo: ${esc(f.doble.tipo_ingreso)} · Entidad: ${esc(f.doble.entidad)} · Desde: ${esc(f.doble.fecha_inicio)} · Importe mensual: ${esc(f.doble.importe)}</p>`:''}<p>Soy jubilado: <b>${f.doble.es_jubilado?'SI':'NO'}</b> · Trámite cese renta: <b>${f.doble.tramite_cese?'SI':'NO'}</b></p><p>Fecha: ${esc(f.doble.fecha_declaracion)}</p></div>`)}
    if(type==='incompatibilidad'){Object.assign(f.incompatibilidad,{acepta:document.getElementById('inc_acepta').checked,fecha_declaracion:elv('inc_fecha')});S.save();showModal('Declaración de Incompatibilidades',`<div class="preview"><h2>DECLARACIÓN DE INCOMPATIBILIDADES, CONFLICTO DE INTERÉS Y PROHIBICIONES</h2><p>Yo, <b>${esc(personName())}</b>, con C.I. <b>${esc(pr.persona.ci)}</b>, servidor público de SEDEGES, ${f.incompatibilidad.acepta?'declaro no estar comprendido en las incompatibilidades, conflictos de interés y prohibiciones señaladas en el formulario institucional.':'declaración pendiente de aceptación.'}</p><p>La Paz, ${esc(f.incompatibilidad.fecha_declaracion)}</p></div>`)} }

  function renderFamilia(){const arr=S.get().familia;document.getElementById('view-familia').innerHTML=`<div class="page-head"><div><h3>Familia y posibles coincidencias de parentesco</h3><p>Se registra la declaración familiar como datos, no certificados escaneados. El prototipo solo genera una alerta de posible coincidencia para revisión.</p></div><button class="btn primary" id="addFamily">+ Familiar</button></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Parentesco</th><th>Nombres</th><th>Apellido paterno</th><th>Apellido materno</th><th>Resultado</th><th></th></tr></thead><tbody>${arr.length?arr.map((x,i)=>`<tr><td>${esc(x.parentesco)}</td><td>${esc(x.nombres)}</td><td>${esc(x.paterno)}</td><td>${esc(x.materno)}</td><td>${familyMatch(x)?'<span class="status pending">Posible coincidencia</span>':'<span class="status ok">Sin coincidencia</span>'}</td><td><button class="btn small danger" data-family-del="${i}">Quitar</button></td></tr>`).join(''):'<tr><td colspan="6" class="muted">Sin familiares registrados.</td></tr>'}</tbody></table></div></div>`;document.getElementById('addFamily').onclick=()=>showModal('Registrar familiar',`<div class="form-grid"><div class="field"><label>Parentesco</label><select id="fam_rel">${D.relationships.map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Nombres</label><input id="fam_nom"></div><div class="field"><label>Apellido paterno</label><input id="fam_pat"></div><div class="field"><label>Apellido materno</label><input id="fam_mat"></div></div><div class="toolbar" style="margin-top:16px"><button class="btn primary" id="saveFam">Guardar</button></div>`);setTimeout(()=>{const b=document.getElementById('saveFam');if(b)b.onclick=()=>{S.push('familiares',{parentesco:elv('fam_rel'),nombres:elv('fam_nom'),paterno:elv('fam_pat'),materno:elv('fam_mat')});closeModal();renderFamilia()}},0);document.querySelectorAll('[data-family-del]').forEach(b=>b.onclick=()=>{S.get().familiares.splice(+b.dataset.familyDel,1);S.save();renderFamilia()})}
  function familyMatch(x){const me=p().persona;const names=[me.apellido_paterno,me.apellido_materno].filter(Boolean).map(s=>s.toLowerCase());return [x.paterno,x.materno].filter(Boolean).some(s=>names.includes(s.toLowerCase()))}

  function renderCaja(){const rows=S.get().cajaSalud;document.getElementById('view-caja').innerHTML=`<div class="page-head"><div><h3>Alta y Baja en Caja de Salud</h3><p>Se controla la documentación requerida y se registra el movimiento; no se almacena la fotocopia o formulario escaneado.</p></div></div><div class="grid two"><div class="card"><h4>Registrar ALTA</h4>${healthChecklist('alta',['Fotocopia de carnet','Certificado de nacimiento','Preocupacional','Memorándum de asignación','Formulario AVC-04'])}</div><div class="card"><h4>Registrar BAJA</h4>${healthChecklist('baja',['Fotocopia de carnet','Copia del memorándum de asignación','Formulario AVC-04','Formulario AVC-07'])}</div></div><div class="card" style="margin-top:16px"><h4>Movimientos registrados</h4>${simpleHistoryTable(rows)}</div>`;document.querySelectorAll('[data-healthsave]').forEach(b=>b.onclick=()=>saveHealth(b.dataset.healthsave))}
  function healthChecklist(type,items){return `<p class="tiny muted">${profileSummary()}</p>${items.map((x,i)=>`<label style="display:block;margin:9px 0"><input type="checkbox" data-health="${type}" data-i="${i}"> ${esc(x)}</label>`).join('')}<div class="field"><label>Fecha</label><input type="date" id="health_date_${type}" value="${today()}"></div><button class="btn primary" data-healthsave="${type}" style="margin-top:12px">Registrar ${type.toUpperCase()}</button>`}
  function saveHealth(type){const checks=[...document.querySelectorAll(`[data-health="${type}"]`)];const missing=checks.filter(x=>!x.checked);if(missing.length&&!confirm(`Hay ${missing.length} requisito(s) sin marcar. ¿Registrar de todos modos?`))return;const date=document.getElementById('health_date_'+type).value;const obj={fecha:date,tipo:type.toUpperCase(),cumplidos:checks.length-missing.length,total:checks.length};S.push('cajaSalud',obj);addHistory('CAJA DE SALUD',`${obj.tipo} registrada (${obj.cumplidos}/${obj.total} requisitos marcados)`);renderCaja()}
  function simpleHistoryTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Detalle</th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${esc(x.fecha)}</td><td>${esc(x.tipo)}</td><td>${x.cumplidos!==undefined?`${x.cumplidos}/${x.total} requisitos`:esc(x.detalle||'')}</td></tr>`).join(''):'<tr><td colspan="3" class="muted">Sin registros.</td></tr>'}</tbody></table></div>`}

  function renderVacaciones(){const rows=S.get().vacaciones;document.getElementById('view-vacaciones').innerHTML=`<div class="page-head"><div><h3>Vacaciones</h3><p>La fecha de ingreso se reutiliza desde la ficha. El prototipo calcula la fecha final contando días hábiles de lunes a viernes.</p></div></div><div class="grid two"><div class="card"><h4>Nueva vacación</h4><div class="form-grid"><div class="field"><label>Fecha de ingreso</label><input class="readonly" readonly value="${esc(p().institucional.fecha_ingreso)}"></div><div class="field"><label>Gestión</label><input id="vac_gestion" placeholder="Ej. 2025-2026"></div><div class="field"><label>Días disponibles</label><input type="number" id="vac_disp" min="0"></div><div class="field"><label>Días solicitados</label><input type="number" id="vac_dias" min="1"></div><div class="field"><label>Fecha inicio</label><input type="date" id="vac_inicio"></div><div class="field"><label>Fecha fin calculada</label><input class="readonly" readonly id="vac_fin"></div></div><div class="toolbar" style="margin-top:12px"><button class="btn" id="calcVac">Calcular</button><button class="btn primary" id="saveVac">Registrar</button></div><p class="tiny muted">Los feriados institucionales deben parametrizarse en producción; este demo excluye sábados y domingos.</p></div><div class="card"><h4>Vacaciones registradas</h4>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Gestión</th><th>Inicio</th><th>Fin</th><th>Días</th><th>Saldo</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.gestion)}</td><td>${x.inicio}</td><td>${x.fin}</td><td>${x.dias}</td><td>${x.saldo}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">Sin vacaciones registradas.</p>'}</div></div>`;document.getElementById('calcVac').onclick=()=>{document.getElementById('vac_fin').value=businessEnd(elv('vac_inicio'),+elv('vac_dias'))};document.getElementById('saveVac').onclick=()=>{if(!elv('vac_inicio')||!+elv('vac_dias'))return alert('Ingrese fecha de inicio y días solicitados.');const fin=businessEnd(elv('vac_inicio'),+elv('vac_dias'));const disp=+elv('vac_disp')||0;const obj={gestion:elv('vac_gestion'),inicio:elv('vac_inicio'),fin,dias:+elv('vac_dias'),disponibles:disp,saldo:disp-(+elv('vac_dias'))};S.push('vacaciones',obj);addHistory('VACACIONES',`${obj.dias} días de la gestión ${obj.gestion}: ${obj.inicio} a ${obj.fin}`);renderVacaciones()}}
  function businessEnd(start,days){if(!start||!days)return'';let d=new Date(start+'T12:00:00'),count=0;while(count<days){const day=d.getDay();if(day!==0&&day!==6)count++;if(count<days)d.setDate(d.getDate()+1)}return d.toISOString().slice(0,10)}

  function renderCertificados(){const rows=S.get().certificados;document.getElementById('view-certificados').innerHTML=`<div class="page-head"><div><h3>Certificado de trabajo</h3><p>El certificado toma automáticamente los datos personales y la trayectoria registrada en el historial.</p></div></div><div class="grid two"><div class="card"><h4>Nueva solicitud</h4><div class="form-grid"><div class="field"><label>Nº / referencia de nota de solicitud</label><input id="cert_nota"></div><div class="field"><label>Voucher de pago (Nº / referencia)</label><input id="cert_voucher"></div><div class="field"><label>Fecha solicitud</label><input type="date" id="cert_fecha" value="${today()}"></div></div><div class="toolbar" style="margin-top:12px"><button class="btn primary" id="genCert">Generar certificado</button></div></div><div class="card"><h4>Solicitudes registradas</h4>${rows.length?simpleHistoryTable(rows.map(x=>({fecha:x.fecha_solicitud,tipo:'CERTIFICADO',detalle:`Nota ${x.nota} · Voucher ${x.voucher}`}))):'<p class="muted">Sin solicitudes.</p>'}</div></div>`;document.getElementById('genCert').onclick=()=>{const obj={nota:elv('cert_nota'),voucher:elv('cert_voucher'),fecha_solicitud:elv('cert_fecha'),fecha_emision:today()};S.push('certificados',obj);addHistory('CERTIFICADO',`Certificado generado. Nota ${obj.nota||'s/n'}`);showModal('Certificado de Trabajo',certificatePreview(obj))}}
  function certificatePreview(obj){const pr=p(),hist=S.get().historial.filter(x=>['DESIGNACIÓN','MOVIMIENTO','COMISIÓN','INGRESO'].includes(x.tipo));return `<div class="preview"><h2>CERTIFICADO DE TRABAJO</h2><p>Se certifica que <b>${esc(personName())}</b>, con C.I. <b>${esc(pr.persona.ci)}</b>, registra en Kardex la siguiente información institucional:</p><p><b>Fecha de ingreso:</b> ${esc(pr.institucional.fecha_ingreso||'—')}<br><b>Ítem:</b> ${esc(pr.institucional.numero_item||'—')}<br><b>Denominación de puesto:</b> ${esc(pr.institucional.denominacion_puesto||'—')}<br><b>Puesto funcional:</b> ${esc(pr.institucional.puesto_funcional||'—')}<br><b>Unidad:</b> ${esc(pr.institucional.unidad_administrativa||'—')}</p><h3>Historial de movimientos / comisiones</h3>${hist.length?'<ul>'+hist.map(x=>`<li>${esc(x.fecha)} — ${esc(x.detalle)}</li>`).join('')+'</ul>':'<p>Sin movimientos adicionales registrados en este prototipo.</p>'}<p>Solicitud: ${esc(obj.nota)} · Voucher: ${esc(obj.voucher)} · Fecha emisión: ${esc(obj.fecha_emision)}</p></div>`}

  function renderAccidentes(){document.getElementById('view-accidentes').innerHTML=`<div class="page-head"><div><h3>Accidentes de trabajo</h3><p>Plantilla digital basada en el formulario proporcionado. Los datos ya existentes del trabajador se autocompletan y solo se completa la información específica del accidente.</p></div><button class="btn" id="accList">Ver registrados (${S.get().accidentes.length})</button></div><div class="card"><div class="wizard">${['Trabajador','Dirección','Laboral','Accidente','Atención','Ente Gestor','Clasificación'].map((x,i)=>`<button class="${i===0?'active':''}" data-wiz="${i}">${i+1}. ${x}</button>`).join('')}</div>${accidentPanes()}</div>`;document.querySelectorAll('[data-wiz]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-wiz],.wizard-pane').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector(`[data-wizpane="${b.dataset.wiz}"]`).classList.add('active')});document.getElementById('saveAccident').onclick=saveAccident;document.getElementById('exportAccident').onclick=exportAccidentCsv;document.getElementById('accList').onclick=()=>showModal('Accidentes registrados',simpleHistoryTable(S.get().accidentes.map(x=>({fecha:x.fecha,tipo:'ACCIDENTE',detalle:`${x.lugar||''} · ${x.descripcion||''}`}))))}
  function accidentPanes(){const pr=p();return `
    <div class="wizard-pane active" data-wizpane="0"><div class="callout">Autocompletado desde Kardex: ${profileSummary()}</div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Apellido paterno</label><input class="readonly" readonly id="ac_paterno" value="${esc(pr.persona.apellido_paterno)}"></div><div class="field"><label>Apellido materno</label><input class="readonly" readonly id="ac_materno" value="${esc(pr.persona.apellido_materno)}"></div><div class="field"><label>Apellido de casada</label><input id="ac_casada"></div><div class="field"><label>Nombres</label><input class="readonly" readonly id="ac_nombres" value="${esc(pr.persona.nombres)}"></div><div class="field"><label>CUA</label><input class="readonly" readonly id="ac_cua" value="${esc(pr.bancario.nua_cua)}"></div><div class="field"><label>Matrícula asegurado</label><input id="ac_matricula"></div><div class="field"><label>Ente Gestor de Salud</label><input id="ac_gestor" value="CAJA NACIONAL DE SALUD"></div><div class="field"><label>Fecha de nacimiento</label><input class="readonly" readonly id="ac_nac" value="${esc(pr.persona.fecha_nacimiento)}"></div><div class="field"><label>C.I.</label><input class="readonly" readonly id="ac_ci" value="${esc(pr.persona.ci)}"></div><div class="field"><label>RUN</label><input id="ac_run"></div><div class="field"><label>Otros</label><input id="ac_otros"></div><div class="field"><label>Sexo</label><input class="readonly" readonly id="ac_sexo" value="${esc(pr.persona.genero)}"></div><div class="field"><label>Estado civil</label><input class="readonly" readonly id="ac_ec" value="${esc(pr.persona.estado_civil)}"></div><div class="field"><label>Nacionalidad</label><input class="readonly" readonly id="ac_nac2" value="${esc(pr.persona.nacionalidad)}"></div></div></div>
    <div class="wizard-pane" data-wizpane="1"><h4>Dirección del trabajador</h4><div class="form-grid"><div class="field"><label>Departamento</label><input id="ac_dir_dep"></div><div class="field"><label>Provincia</label><input id="ac_dir_prov" value="${esc(pr.persona.provincia)}"></div><div class="field"><label>Ciudad / Localidad</label><input id="ac_dir_ciudad" value="${esc(pr.persona.ciudad)}"></div><div class="field"><label>Zona / Barrio / Urbanización</label><input id="ac_dir_zona"></div><div class="field"><label>Teléfono / Otros</label><input id="ac_dir_tel" value="${esc(pr.persona.telefono)}"></div><div class="field"><label>Avenida</label><input id="ac_dir_av"></div><div class="field"><label>Calle</label><input id="ac_dir_calle"></div><div class="field"><label>Pasaje</label><input id="ac_dir_pasaje"></div><div class="field"><label>Número</label><input id="ac_dir_num"></div><div class="field"><label>Edificio</label><input id="ac_dir_edif"></div><div class="field"><label>Bloque</label><input id="ac_dir_bloque"></div><div class="field"><label>Departamento (vivienda)</label><input id="ac_dir_dpto"></div></div></div>
    <div class="wizard-pane" data-wizpane="2"><h4>Información laboral</h4><div class="form-grid"><div class="field"><label>Tipo trabajador</label><select id="ac_tipo_trab"><option>DEPENDIENTE</option><option>INDEPENDIENTE</option></select></div><div class="field"><label>NIT asegurado independiente</label><input id="ac_nit_ind"></div><div class="field"><label>Fecha inicio relación laboral</label><input type="date" class="readonly" readonly id="ac_ini_rel" value="${esc(pr.institucional.fecha_ingreso)}"></div><div class="field"><label>Ocupación</label><input id="ac_ocup" value="${esc(pr.institucional.puesto_funcional)}"></div><div class="field wide"><label>Nombre / razón social del empleador</label><input id="ac_empleador" value="SERVICIO DEPARTAMENTAL DE GESTIÓN SOCIAL - SEDEGES"></div><div class="field"><label>Teléfono empleador</label><input id="ac_emp_tel"></div><div class="field"><label>Fax</label><input id="ac_emp_fax"></div><div class="field"><label>Otros</label><input id="ac_emp_otros"></div><div class="field"><label>Número patronal</label><input id="ac_patronal"></div><div class="field"><label>NIT/GOB empleador</label><input id="ac_nit_emp"></div><div class="field"><label>Departamento</label><input id="ac_emp_dep"></div><div class="field"><label>Provincia</label><input id="ac_emp_prov"></div><div class="field"><label>Ciudad / Localidad</label><input id="ac_emp_ciudad"></div><div class="field"><label>Zona / Barrio / Urbanización</label><input id="ac_emp_zona"></div><div class="field"><label>Avenida</label><input id="ac_emp_av"></div><div class="field"><label>Calle</label><input id="ac_emp_calle"></div><div class="field"><label>Pasaje</label><input id="ac_emp_pasaje"></div><div class="field"><label>Número</label><input id="ac_emp_num"></div><div class="field"><label>Edificio</label><input id="ac_emp_edif"></div><div class="field"><label>Bloque</label><input id="ac_emp_bloque"></div><div class="field"><label>Piso</label><input id="ac_emp_piso"></div><div class="field"><label>Oficina</label><input id="ac_emp_oficina"></div><div class="field"><label>¿Recibió entrenamiento previo?</label><select id="ac_entren"><option>SI</option><option>NO</option></select></div><div class="field"><label>Tiempo de servicio en la empresa</label><input id="ac_tiempo_emp"></div><div class="field"><label>Tiempo en la ocupación</label><input id="ac_tiempo_ocup"></div><div class="field"><label>¿Recibió instrucciones de Seguridad e Higiene?</label><select id="ac_seg"><option>SI</option><option>NO</option></select></div><div class="field"><label>Sección donde trabaja</label><input id="ac_seccion" value="${esc(pr.institucional.instituto_centro_oficina)}"></div></div></div>
    <div class="wizard-pane" data-wizpane="3"><h4>Datos del accidente</h4><div class="form-grid"><div class="field wide"><label>Lugar donde ocurrió</label><input id="ac_lugar"></div><div class="field"><label>Fecha</label><input type="date" id="ac_fecha"></div><div class="field"><label>Hora</label><input type="time" id="ac_hora"></div><div class="field full"><label>¿Cómo ocurrió el accidente?</label><textarea id="ac_como"></textarea></div><div class="field full"><label>Descripción de las causas</label><textarea id="ac_causas"></textarea></div><div class="field full"><label>¿Qué labor realizaba al producirse el accidente?</label><textarea id="ac_labor"></textarea></div><div class="field"><label>Testigo 1</label><input id="ac_testigo1"></div><div class="field"><label>Testigo 2</label><input id="ac_testigo2"></div></div></div>
    <div class="wizard-pane" data-wizpane="4"><h4>Atención inicial</h4><div class="form-grid"><div class="field"><label>El accidente fue atendido en</label><select id="ac_at_lugar"><option>El mismo lugar del accidente</option><option>Posta Sanitaria</option><option>No recibió atención</option></select></div><div class="field"><label>Fecha atención de urgencia</label><input type="date" id="ac_at_fecha"></div><div class="field"><label>Hora atención</label><input type="time" id="ac_at_hora"></div><div class="field"><label>¿Quién prestó primeros auxilios?</label><input id="ac_at_quien"></div><div class="field full"><label>Partes corporales afectadas</label><textarea id="ac_at_partes"></textarea></div><div class="field wide"><label>Diagnóstico presuntivo</label><textarea id="ac_at_diag"></textarea></div><div class="field wide"><label>Tratamiento efectuado</label><textarea id="ac_at_trat"></textarea></div><div class="field"><label>¿Fue trasladado?</label><select id="ac_at_tras"><option>NO</option><option>SI</option></select></div><div class="field"><label>Centro Médico de traslado</label><input id="ac_at_centro"></div></div></div>
    <div class="wizard-pane" data-wizpane="5"><h4>Para ser llenado por el Ente Gestor de Salud</h4><div class="form-grid"><div class="field"><label>Centro Médico u Hospital</label><input id="ac_eg_centro"></div><div class="field"><label>Fecha ingreso</label><input type="date" id="ac_eg_fecha"></div><div class="field"><label>Hora ingreso</label><input type="time" id="ac_eg_hora"></div><div class="field full"><label>Diagnóstico médico inicial</label><textarea id="ac_eg_diag"></textarea></div><div class="field full"><label>Tratamiento efectuado</label><textarea id="ac_eg_trat"></textarea></div><div class="field"><label>Tiempo estimado de incapacidad</label><input id="ac_eg_incap"></div><div class="field"><label>Internación</label><select id="ac_eg_int"><option>NO</option><option>SI</option></select></div><div class="field"><label>Transferido a otro centro</label><select id="ac_eg_trans"><option>NO</option><option>SI</option></select></div><div class="field"><label>Centro al que fue transferido</label><input id="ac_eg_centrotrans"></div><div class="field"><label>Causa transferencia</label><input id="ac_eg_causa"></div><div class="field"><label>Fecha fallecimiento</label><input type="date" id="ac_eg_fall_fecha"></div><div class="field"><label>Hora fallecimiento</label><input type="time" id="ac_eg_fall_hora"></div><div class="field"><label>Fecha del informe</label><input type="date" id="ac_eg_inf_fecha"></div><div class="field"><label>Hora del informe</label><input type="time" id="ac_eg_inf_hora"></div><div class="field"><label>Lugar de recepción por la Gestora</label><input id="ac_eg_lugar_rec"></div><div class="field"><label>Fecha recepción Gestora</label><input type="date" id="ac_eg_fecha_rec"></div><div class="field"><label>Responsable Gestora</label><input id="ac_eg_resp"></div></div></div>
    <div class="wizard-pane" data-wizpane="6"><h4>Datos para análisis del accidente</h4><div class="form-grid">${catalogSelect('tipo_accidente','Tipo de accidente')}${catalogSelect('agente_involucrado','Agente involucrado')}${catalogSelect('naturaleza_dano','Naturaleza del daño')}${catalogSelect('parte_cuerpo','Parte afectada del cuerpo')}${catalogSelect('condicion_peligrosa','Condición peligrosa')}${catalogSelect('acto_inseguro','Acto inseguro')}${catalogSelect('factor_contribuyente','Factor contribuyente')}</div><div class="callout warn" style="margin-top:12px">El formulario entregado indica presentación por el empleador dentro de 24 horas y distribución en 5 copias; la entrega posterior señala 5 días en área urbana y 10 días en área rural.</div><div class="toolbar" style="margin-top:12px"><button class="btn primary" id="saveAccident">Guardar accidente</button><button class="btn" id="exportAccident">Exportar CSV compatible con Excel</button></div></div>`}
  function catalogSelect(key,label){return `<div class="field"><label>${label}</label><select id="cat_${key}"><option value=""></option>${D.accidentCatalogs[key].map(x=>`<option value="${x.id}">${x.id}. ${esc(x.nombre)}</option>`).join('')}</select></div>`}
  function elv(id){const e=document.getElementById(id);return e?e.value:''}
  function saveAccident(){const obj={fecha:elv('ac_fecha'),hora:elv('ac_hora'),lugar:elv('ac_lugar'),descripcion:elv('ac_como'),causas:elv('ac_causas'),labor:elv('ac_labor'),matricula:elv('ac_matricula'),ente_gestor:elv('ac_gestor'),run:elv('ac_run'),otros:elv('ac_otros'),direccion:{departamento:elv('ac_dir_dep'),provincia:elv('ac_dir_prov'),ciudad:elv('ac_dir_ciudad'),zona:elv('ac_dir_zona'),telefono:elv('ac_dir_tel'),avenida:elv('ac_dir_av'),calle:elv('ac_dir_calle'),pasaje:elv('ac_dir_pasaje'),numero:elv('ac_dir_num'),edificio:elv('ac_dir_edif'),bloque:elv('ac_dir_bloque'),departamento_vivienda:elv('ac_dir_dpto')},laboral:{tipo:elv('ac_tipo_trab'),nit_ind:elv('ac_nit_ind'),ocupacion:elv('ac_ocup'),empleador:elv('ac_empleador'),telefono:elv('ac_emp_tel'),fax:elv('ac_emp_fax'),otros:elv('ac_emp_otros'),patronal:elv('ac_patronal'),nit:elv('ac_nit_emp'),departamento:elv('ac_emp_dep'),provincia:elv('ac_emp_prov'),ciudad:elv('ac_emp_ciudad'),zona:elv('ac_emp_zona'),avenida:elv('ac_emp_av'),calle:elv('ac_emp_calle'),pasaje:elv('ac_emp_pasaje'),numero:elv('ac_emp_num'),edificio:elv('ac_emp_edif'),bloque:elv('ac_emp_bloque'),piso:elv('ac_emp_piso'),oficina:elv('ac_emp_oficina'),entrenamiento:elv('ac_entren'),tiempo_empresa:elv('ac_tiempo_emp'),tiempo_ocupacion:elv('ac_tiempo_ocup'),seguridad_higiene:elv('ac_seg'),seccion:elv('ac_seccion')},testigos:[elv('ac_testigo1'),elv('ac_testigo2')],atencion:{lugar:elv('ac_at_lugar'),fecha:elv('ac_at_fecha'),hora:elv('ac_at_hora'),quien:elv('ac_at_quien'),partes:elv('ac_at_partes'),diagnostico:elv('ac_at_diag'),tratamiento:elv('ac_at_trat'),traslado:elv('ac_at_tras'),centro:elv('ac_at_centro')},ente:{centro:elv('ac_eg_centro'),fecha:elv('ac_eg_fecha'),hora:elv('ac_eg_hora'),diagnostico:elv('ac_eg_diag'),tratamiento:elv('ac_eg_trat'),incapacidad:elv('ac_eg_incap'),internacion:elv('ac_eg_int'),transferido:elv('ac_eg_trans'),centro_transferido:elv('ac_eg_centrotrans'),causa:elv('ac_eg_causa'),fallecimiento_fecha:elv('ac_eg_fall_fecha'),fallecimiento_hora:elv('ac_eg_fall_hora'),informe_fecha:elv('ac_eg_inf_fecha'),informe_hora:elv('ac_eg_inf_hora'),lugar_recepcion:elv('ac_eg_lugar_rec'),fecha_recepcion:elv('ac_eg_fecha_rec'),responsable:elv('ac_eg_resp')},clasificacion:{tipo_accidente:elv('cat_tipo_accidente'),agente_involucrado:elv('cat_agente_involucrado'),naturaleza_dano:elv('cat_naturaleza_dano'),parte_cuerpo:elv('cat_parte_cuerpo'),condicion_peligrosa:elv('cat_condicion_peligrosa'),acto_inseguro:elv('cat_acto_inseguro'),factor_contribuyente:elv('cat_factor_contribuyente')}};S.push('accidentes',obj);addHistory('ACCIDENTE DE TRABAJO',`${obj.fecha||today()} · ${obj.lugar||'Lugar pendiente'}`);alert('Accidente guardado en el prototipo.')}
  function exportAccidentCsv(){const latest=S.get().accidentes.at(-1);if(!latest)return alert('Primero guarde un accidente.');const flat=flatten({persona:p().persona,institucional:p().institucional,seguridad:p().bancario,accidente:latest});const csv='Campo,Valor\n'+Object.entries(flat).map(([k,v])=>`"${String(k).replace(/"/g,'""')}","${String(v??'').replace(/"/g,'""')}"`).join('\n');download('accidente_trabajo_demo.csv',csv,'text/csv;charset=utf-8')}
  function flatten(o,prefix='',out={}){Object.entries(o||{}).forEach(([k,v])=>{const key=prefix?prefix+'.'+k:k;if(v&&typeof v==='object'&&!Array.isArray(v))flatten(v,key,out);else out[key]=Array.isArray(v)?v.join(' | '):v});return out}
  function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}

  function renderHistorial(){const rows=[...S.get().historial].reverse();document.getElementById('view-historial').innerHTML=`<div class="page-head"><div><h3>Historial del funcionario</h3><p>Todos los procesos relevantes se agregan como eventos cronológicos para que los certificados y consultas futuras no dependan de volver a buscar carpetas.</p></div><button class="btn" id="addHist">+ Evento manual de demo</button></div><div class="card"><p>${profileSummary()}</p><div class="timeline">${rows.map(x=>`<div class="event"><time>${esc(x.fecha)}</time><b>${esc(x.tipo)}</b><div>${esc(x.detalle)}</div></div>`).join('')}</div></div>`;document.getElementById('addHist').onclick=()=>showModal('Agregar evento al historial',`<div class="form-grid"><div class="field"><label>Tipo</label><select id="hm_tipo"><option>MOVIMIENTO</option><option>COMISIÓN</option><option>MEMORÁNDUM</option><option>BAJA</option><option>OTRO</option></select></div><div class="field"><label>Fecha</label><input type="date" id="hm_fecha" value="${today()}"></div><div class="field full"><label>Detalle</label><textarea id="hm_det"></textarea></div></div><button class="btn primary" id="hm_save" style="margin-top:12px">Guardar</button>`);setTimeout(()=>{if(document.getElementById('hm_save'))hm_save.onclick=()=>{S.push('historial',{fecha:elv('hm_fecha'),tipo:elv('hm_tipo'),detalle:elv('hm_det')});closeModal();renderHistorial()}},0)}

  function renderMapa(){const groups=[
    ['personas',['ci','expedicion','nombres','apellido_paterno','apellido_materno','fecha_nacimiento','lugar_nacimiento','provincia','nacionalidad','genero','estado_civil','telefono','correo_electronico','facebook','libreta_servicio_militar'],['registrar','buscarPorCI','actualizar','consultar']],
    ['kardex',['persona_id','fecha_registro','fecha_actualizacion','estado'],['crear','consultar','actualizar','consultarHistorial']],
    ['ficha_personal',['kardex_id','gestion','fecha_actualizacion'],['crearFicha','actualizarFicha','generarFormulario']],
    ['formacion_academica',['persona_id','grado_formacion','carrera_area_especialidad','institucion','fecha_extension_titulo'],['registrar','actualizar','consultar']],
    ['cursos',['persona_id','nombre','fecha_inicio','fecha_fin','duracion_horas'],['registrar','actualizar']],
    ['experiencia_laboral',['persona_id','entidad_empresa','cargo_desempenado','fecha_inicio','fecha_fin'],['registrar','actualizar','calcularDuracion']],
    ['items',['numero_item','dependencia','denominacion_puesto','puesto_funcional','haber_mensual','estado'],['buscarPorNumero','asignar','marcarAcefalo']],
    ['vinculaciones',['persona_id','item_id','fecha_ingreso','fecha_fin','dependencia','centro_ubicacion','estado'],['registrarIngreso','actualizarUbicacion','finalizar']],
    ['requisitos / checklist',['numero','nombre','estado','fecha_revision','observacion'],['marcarPresentado','marcarPendiente','marcarNoCorresponde','verificarCompleto']],
    ['acta_posesion',['vinculacion_id','ciudad','fecha','hora'],['generar','consultar']],
    ['acta_induccion',['vinculacion_id','inmediato_superior','dependencia','numero_item','fecha'],['generar','verificarCompleta']],
    ['doble_percepcion',['persona_id','percibe_recursos_estado','es_jubilado','tramite_cese_renta','fecha_declaracion'],['registrar','generarFormulario']],
    ['percepciones_economicas',['declaracion_id','tipo_ingreso','otro_tipo','entidad','fecha_inicio','importe_mensual','regimen_pension','entidad_aguinaldo'],['registrar','actualizar']],
    ['familiares',['persona_id','tipo_parentesco','nombres','apellido_paterno','apellido_materno'],['registrar','buscarCoincidencias']],
    ['movimientos_caja_salud',['persona_id','tipo_movimiento','fecha','estado'],['registrarAlta','registrarBaja','verificarRequisitos']],
    ['vacaciones',['persona_id','gestion','dias_disponibles','dias_utilizados','fecha_inicio','fecha_fin','dias_solicitados'],['calcularDiasHabiles','calcularSaldo','registrar']],
    ['historial_laboral',['persona_id','fecha','tipo','detalle'],['registrarMovimiento','consultarHistorial']],
    ['certificados_trabajo',['persona_id','numero_nota','voucher_pago','fecha_solicitud','fecha_emision'],['consultarHistorial','generarCertificado','exportar']],
    ['accidentes_trabajo',['persona_id','fecha','hora','lugar','descripcion','causas','labor_realizada'],['autocompletarDatos','registrar','generarFormulario','exportarExcel']],
    ['catalogo_accidente',['categoria','codigo','nombre'],['listarPorCategoria']]
  ];document.getElementById('view-mapa').innerHTML=`<div class="page-head"><div><h3>Mapa de datos para validación</h3><p>Vista resumida de las tablas principales, atributos y acciones previstas. En producción, los métodos se implementan en la aplicación/API, no dentro de las tablas PostgreSQL.</p></div></div>.</div><div class="grid three data-map" style="margin-top:16px">${groups.map(g=>`<div class="card"><h4>${esc(g[0])}</h4><b class="tiny">Atributos</b><ul>${g[1].map(x=>`<li>${esc(x)}</li>`).join('')}</ul><b class="tiny">Acciones</b><div>${g[2].map(x=>`<span class="method">${esc(x)}()</span>`).join('')}</div></div>`).join('')}</div>`}

  const renderers={dashboard:renderDashboard,preregistro:renderPreregistro,ficha:renderFicha,hojavida:renderHojaVida,formularios:renderFormularios,familia:renderFamilia,caja:renderCaja,vacaciones:renderVacaciones,certificados:renderCertificados,accidentes:renderAccidentes,historial:renderHistorial,mapa:renderMapa};
  document.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)setView(b.dataset.view)});
  document.getElementById('closeModal').onclick=closeModal;document.getElementById('modal').onclick=e=>{if(e.target.id==='modal')closeModal()};
  document.getElementById('resetData').onclick=()=>{if(confirm('¿Reiniciar todos los datos del prototipo?'))S.reset()};document.getElementById('loadDemo').onclick=()=>{S.reset()};
  setView(S.get().ui.activeView||'dashboard');
})();
